  // Capture (P-RF01)
  getIt.registerLazySingleton<AudioRecorderDataSource>(
    AudioRecorderDataSource.new,
  );
  getIt.registerLazySingleton<AudioCaptureRepository>(
    () => AudioCaptureRepositoryImpl(getIt<AudioRecorderDataSource>()),
