71	  String? _pendingAudioPath;
72	  String? _pendingImagePath;
73	  Timer? _audioTicker;
74	
75	  /// Guards against discarding the same recording twice when both the
76	  /// explicit `ModalClosed` handler and `close()`'s disposal-time fallback
77	  /// (for the swipe-down/tap-outside dismissal that bypasses `ModalClosed`)
78	  /// would otherwise race on the same still-recording state.
