82	      state is InsertionModalAudioProcessing ||
83	      state is InsertionModalAudioTranscribed ||
84	      state is InsertionModalAudioSaving ||
85	      state is InsertionModalAudioSaveFailure ||
86	      state is InsertionModalAudioFailure;
87	
88	  bool _isFotoAbandonable(InsertionModalState state) =>
89	      state is InsertionModalFotoProcessing ||
90	      state is InsertionModalFotoReconhecido ||
91	      state is InsertionModalFotoSaving ||
92	      state is InsertionModalFotoSaveFailure ||
93	      state is InsertionModalFotoFailure;
