95	  Future<void> _onTabSelected(
96	    TabSelected event,
97	    Emitter<InsertionModalState> emit,
98	  ) async {
99	    final current = state;
100	    if (current is InsertionModalAudioRecording) {
101	      // Switching away mid-recording discards it (Edge Cases) — nothing
102	      // from an abandoned capture may survive (FR-011).
103	      _audioCaptureRepository.discard();
104	      _recordingDiscarded = true;
105	      _stopAudioTicker();
106	      _pendingAudioPath = null;
107	    } else if (_isAudioAbandonable(current)) {
108	      // Leaving any in-flight/reviewed/failed Áudio sub-state abandons the
109	      // held audio and any unsaved review edits (FR-011, data-model.md's
110	      // transition table).
111	      _pendingAudioPath = null;
112	    }
113	
114	    if (_isFotoAbandonable(current)) {
115	      _pendingImagePath = null;
116	    }
117	
118	    switch (event.tab) {
119	      case CaptureTab.texto:
120	        emit(InsertionModalTexto(text: _textDraft));
121	      case CaptureTab.audio:
122	        emit(const InsertionModalAudioIdle());
123	      case CaptureTab.foto:
124	        emit(const InsertionModalFotoCaptura());
125	    }
126	  }
127	
128	  Future<void> _onAudioStartRequested(
129	    AudioStartRequested event,
130	    Emitter<InsertionModalState> emit,
131	  ) async {
132	    if (state is! InsertionModalAudioIdle) return;
133	
134	    final hasPermission = await _audioCaptureRepository.hasPermission();
135	    if (!hasPermission) {
136	      emit(const InsertionModalAudioPermissionDenied());
137	      return;
138	    }
139	    await _audioCaptureRepository.start();
140	    _recordingDiscarded = false;
141	    emit(const InsertionModalAudioRecording(elapsed: Duration.zero));
142	    _startAudioTicker();
143	  }
