236	    result.match(
237	      (failure) => emit(
238	        InsertionModalAudioFailure(
239	          duration: duration,
240	          message: _recognitionFailureMessage(failure),
241	        ),
242	      ),
243	      (text) =>
244	          emit(InsertionModalAudioTranscribed(text: text, duration: duration)),
245	    );
246	  }
247	
248	  String _recognitionFailureMessage(RecognitionFailure failure) =>
249	      switch (failure) {
250	        EmptyRecognitionResult() => _noSpeechMessage,
251	        TranscriptionError() => _genericAudioMessage,
252	      };
253	
254	  void _onAudioReviewTextChanged(
255	    AudioReviewTextChanged event,
256	    Emitter<InsertionModalState> emit,
257	  ) {
258	    final current = state;
259	    if (current is InsertionModalAudioTranscribed) {
260	      emit(
261	        InsertionModalAudioTranscribed(
262	          text: event.text,
263	          duration: current.duration,
264	        ),
265	      );
266	    } else if (current is InsertionModalAudioSaveFailure) {
267	      emit(
268	        InsertionModalAudioSaveFailure(
269	          text: event.text,
270	          duration: current.duration,
271	          message: current.message,
272	        ),
273	      );
274	    }
275	  }
276	
277	  Future<void> _onAudioSaveConfirmed(
278	    AudioSaveConfirmed event,
279	    Emitter<InsertionModalState> emit,
280	  ) async {
281	    final current = state;
282	    final (text, duration) = switch (current) {
283	      InsertionModalAudioTranscribed(text: final t, duration: final d) => (
284	        t,
285	        d,
286	      ),
287	      InsertionModalAudioSaveFailure(text: final t, duration: final d) => (
288	        t,
289	        d,
290	      ),
291	      _ => (null, null),
292	    };
293	    if (text == null || duration == null || text.trim().isEmpty) return;
294	
295	    emit(InsertionModalAudioSaving(text: text, duration: duration));
296	    final result = await _confirmEntrySaveUseCase(text, EntrySource.audio);
297	    result.match(
298	      (failure) => emit(
299	        InsertionModalAudioSaveFailure(
300	          text: text,
301	          duration: duration,
302	          message: _confirmSaveFailureMessage(failure),
303	        ),
304	      ),
305	      (entry) {
306	        _pendingAudioPath = null;
307	        _completeSave();
308	      },
309	    );
310	  }
311	
312	  Future<void> _onPhotoSourceSelected(
313	    PhotoSourceSelected event,
314	    Emitter<InsertionModalState> emit,
315	  ) async {
316	    final current = state;
317	    if (current is InsertionModalFotoProcessing ||
318	        current is InsertionModalFotoSaving) {
319	      return;
320	    }
321	
322	    String? path;
323	    try {
324	      path = await _photoCaptureRepository.pickImage(event.source);
325	    } catch (_) {
326	      emit(const InsertionModalFotoPermissionDenied());
327	      return;
328	    }
329	
330	    if (path == null) {
331	      emit(const InsertionModalFotoCaptura());
332	      return;
333	    }
334	
335	    _pendingImagePath = path;
336	    emit(InsertionModalFotoProcessing(imagePath: path));
337	    await _recognizePhoto(path, emit);
338	  }
339	
340	  Future<void> _recognizePhoto(
341	    String imageFilePath,
342	    Emitter<InsertionModalState> emit,
343	  ) async {
344	    final result = await _recognizePhotoUseCase(imageFilePath);
345	
346	    // Same stale-result guard as audio (research.md R6).
347	    if (state is! InsertionModalFotoProcessing ||
348	        _pendingImagePath != imageFilePath) {
349	      return;
350	    }
351	
352	    result.match(
353	      (failure) => emit(
354	        InsertionModalFotoFailure(
355	          imagePath: imageFilePath,
356	          message: _photoRecognitionFailureMessage(failure),
357	        ),
358	      ),
359	      // confidence read but never branched on (Clarification 3).
360	      (ocrResult) => emit(
361	        InsertionModalFotoReconhecido(
362	          imagePath: imageFilePath,
363	          text: ocrResult.text,
364	        ),
365	      ),
366	    );
367	  }
368	
369	  // Every failed OCR call — not just "no text found" — shows the same
370	  // "Foto — Erro" copy (FR-007: "If the OCR call fails (including a
371	  // no-usable-text result)..."), never the raw backend `message`.
372	  String _photoRecognitionFailureMessage(
373	    PhotoRecognitionAttemptFailure failure,
374	  ) => switch (failure) {
375	    PhotoRecognitionOffline() => _offlineMessage,
376	    PhotoRecognitionCallFailed() => _noTextMessage,
377	  };
378	
379	  void _onPhotoReviewTextChanged(
380	    PhotoReviewTextChanged event,
381	    Emitter<InsertionModalState> emit,
382	  ) {
383	    final current = state;
384	    if (current is InsertionModalFotoReconhecido) {
385	      emit(
386	        InsertionModalFotoReconhecido(
387	          imagePath: current.imagePath,
388	          text: event.text,
389	        ),
390	      );
391	    } else if (current is InsertionModalFotoSaveFailure) {
392	      emit(
393	        InsertionModalFotoSaveFailure(
394	          imagePath: current.imagePath,
395	          text: event.text,
396	          message: current.message,
397	        ),
398	      );
399	    }
400	  }
401	
402	  Future<void> _onPhotoSaveConfirmed(
403	    PhotoSaveConfirmed event,
404	    Emitter<InsertionModalState> emit,
405	  ) async {
406	    final current = state;
407	    final (imagePath, text) = switch (current) {
408	      InsertionModalFotoReconhecido(imagePath: final p, text: final t) => (
409	        p,
410	        t,
411	      ),
412	      InsertionModalFotoSaveFailure(imagePath: final p, text: final t) => (
413	        p,
414	        t,
415	      ),
416	      _ => (null, null),
417	    };
418	    if (imagePath == null || text == null || text.trim().isEmpty) return;
419	
420	    await _confirmPhotoSave(imagePath, text, emit);
421	  }
422	
423	  Future<void> _onPhotoSaveWithoutTextRequested(
424	    PhotoSaveWithoutTextRequested event,
425	    Emitter<InsertionModalState> emit,
426	  ) async {
427	    final current = state;
428	    if (current is! InsertionModalFotoFailure) return;
429	
430	    // No further OCR call for this capture (FR-008) — saves immediately
431	    // with the fixed placeholder.
432	    await _confirmPhotoSave(current.imagePath, _photoNoTextPlaceholder, emit);
433	  }
434	
435	  Future<void> _confirmPhotoSave(
436	    String imagePath,
437	    String text,
438	    Emitter<InsertionModalState> emit,
439	  ) async {
440	    emit(InsertionModalFotoSaving(imagePath: imagePath, text: text));
441	    final result = await _confirmEntrySaveUseCase(text, EntrySource.photo);
442	    result.match(
443	      (failure) => emit(
444	        InsertionModalFotoSaveFailure(
445	          imagePath: imagePath,
446	          text: text,
447	          message: _confirmSaveFailureMessage(failure),
448	        ),
449	      ),
450	      (entry) {
451	        _pendingImagePath = null;
452	        _completeSave();
453	      },
454	    );
455	  }
456	
457	  String _confirmSaveFailureMessage(ConfirmEntrySaveFailure failure) =>
458	      switch (failure) {
459	        ConfirmEntrySaveOffline() => _offlineMessage,
460	        ConfirmEntrySaveCreationFailed(failure: final f) => f.message,
461	      };
462	
463	  Future<void> _onRetryRequested(
464	    RetryRequested event,
465	    Emitter<InsertionModalState> emit,
466	  ) async {
467	    final current = state;
468	    final audioPath = _pendingAudioPath;
469	    final imagePath = _pendingImagePath;
470	    if (current is InsertionModalAudioFailure && audioPath != null) {
471	      final duration = current.duration;
472	      emit(InsertionModalAudioProcessing(duration: duration));
473	      await _transcribeAudio(audioPath, duration, emit);
474	    } else if (current is InsertionModalFotoFailure && imagePath != null) {
475	      emit(InsertionModalFotoProcessing(imagePath: imagePath));
476	      await _recognizePhoto(imagePath, emit);
477	    }
478	  }
479	
480	  void _onModalClosed(ModalClosed event, Emitter<InsertionModalState> emit) {
481	    if (state is InsertionModalAudioRecording) {
482	      _audioCaptureRepository.discard();
483	      _recordingDiscarded = true;
484	      _stopAudioTicker();
485	    }
486	    // Unconditionally clears every held capture, regardless of which
487	    // Áudio/Foto sub-state is active when the modal closes (FR-011).
488	    _pendingAudioPath = null;
489	    _pendingImagePath = null;
490	  }
491	
492	  void _completeSave() {
493	    if (!_closeController.isClosed) {
494	      _closeController.add(null);
495	    }
496	  }
497	
498	  @override
499	  Future<void> close() {
500	    if (state is InsertionModalAudioRecording && !_recordingDiscarded) {
501	      // `showModalBottomSheet`'s default swipe-down/tap-outside dismissal
502	      // bypasses `ModalClosed` entirely, so this is the only place that
503	      // reliably catches a still-recording mic at disposal time (FR-011).
504	      _audioCaptureRepository.discard();
505	      _recordingDiscarded = true;
506	      _pendingAudioPath = null;
507	    }
508	    _stopAudioTicker();
509	    unawaited(_closeController.close());
510	    return super.close();
511	  }
512	}
